const W: u32 = 16;
const H: u32 = 12;

/// The 8-bit RGB source of `LOSSY`, `RGBA`, `P3` and `O6`.
fn rgb8() -> Vec<u8> {
    (0..H).flat_map(|y| (0..W).flat_map(move |x| [(x * 255 / (W - 1)) as u8, (y * 255 / (H - 1)) as u8, ((x * y * 7) % 256) as u8])).collect()
}

/// The 8×6 16-bit RGB source of `LL16`.
fn rgb16() -> Vec<u16> {
    (0..6u32).flat_map(|y| (0..8u32).flat_map(move |x| (0..3u32).map(move |c| ((x * 8191 + y * 5003 + c * 12345) % 65536) as u16))).collect()
}

fn gray8() -> Vec<u8> {
    (0..H).flat_map(|y| (0..W).map(move |x| ((x * 16 + y) % 256) as u8)).collect()
}

#[test]
fn every_fixture_is_detected_as_jpeg_xl() {
    for f in [LOSSY, LL16, RGBA, GRAY, P3, O6, ANIM] {
        assert_eq!(detect(f), Some(Format::Jxl));
    }
    assert_eq!(from_extension("photo.JXL"), Some(Format::Jxl));
    assert!(caps(Format::Jxl).read && caps(Format::Jxl).write);
}

#[test]
fn lossy_vardct_decodes_like_libjxl() {
    let img = decode(LOSSY).unwrap();
    assert_eq!((img.dimensions(), img.layout(), img.sample_type()), ((W, H), ChannelLayout::Rgb, SampleType::U8));
    // The same pixels as libjxl's own decoder, to within rounding.
    let libjxl = Image::from_u8(W, H, ChannelLayout::Rgb, LOSSY_LIBJXL.to_vec()).unwrap();
    assert!(max_abs_diff(&img, &libjxl) <= 1.5 / 255.0, "max diff {}", max_abs_diff(&img, &libjxl) * 255.0);
    assert!(img.icc.is_none(), "an sRGB file opens untagged, like every other sRGB image");
    assert!(img.warnings.is_empty(), "{:?}", img.warnings);
}

#[test]
fn lossless_16_bit_is_exact() {
    let img = decode(LL16).unwrap();
    assert_eq!((img.dimensions(), img.layout(), img.sample_type()), ((8, 6), ChannelLayout::Rgb, SampleType::U16));
    assert_eq!(img, Image::from_u16(8, 6, ChannelLayout::Rgb, &rgb16()).unwrap());
}

#[test]
fn alpha_and_gray_decode() {
    let img = decode(RGBA).unwrap();
    assert_eq!(img.layout(), ChannelLayout::Rgba);
    let want: Vec<u8> = rgb8().chunks(3).enumerate().flat_map(|(i, p)| [p[0], p[1], p[2], ((i as u32 % W) * 16 % 256) as u8]).collect();
    assert_eq!(img.data(), &want[..]);

    let img = decode(GRAY).unwrap();
    assert_eq!((img.layout(), img.sample_type()), (ChannelLayout::Gray, SampleType::U8));
    assert!(psnr(&img, &Image::from_u8(W, H, ChannelLayout::Gray, gray8()).unwrap()) > 25.0);
}

#[test]
fn a_wide_gamut_file_keeps_its_profile() {
    let img = decode(P3).unwrap();
    assert_eq!(img.data(), &rgb8()[..], "lossless: the values are the stored ones");
    let icc = img.icc.as_deref().expect("Display P3 is described by a profile");
    assert_eq!(icc.get(36..40), Some(&b"acsp"[..]), "an ICC profile");
}

#[test]
fn orientation_is_applied_and_exif_rewritten() {
    let img = decode(O6).unwrap();
    assert_eq!(img.dimensions(), (H, W), "turned upright: 90° clockwise");
    let exif = img.meta.exif.as_deref().expect("the Brotli-compressed EXIF box is read");
    assert_eq!(exif_orientation(exif), 1, "the pixels are upright, so the tag must not turn them again");
    let src = Image::from_u8(W, H, ChannelLayout::Rgb, rgb8()).unwrap().oriented(6).unwrap();
    assert!(psnr(&img, &src) > 28.0, "PSNR {}", psnr(&img, &src));

    let stored = decode_with(O6, &DecodeOptions { keep_orientation: true, ..Default::default() }).unwrap();
    assert_eq!(stored.dimensions(), (W, H), "keep_orientation gives the stored pixels");
    assert_eq!(stored.oriented(6).unwrap().data(), img.data());
}

#[test]
fn an_animation_opens_its_first_frame_with_a_warning() {
    let img = decode(ANIM).unwrap();
    assert_eq!(img.data(), &rgb8()[..]);
    assert_eq!(img.warnings, vec![DecodeWarning::MoreFrames { total: Some(2) }]);
}

#[test]
fn damaged_files_are_errors_or_warnings_never_panics() {
    for f in [LOSSY, LL16, RGBA, GRAY, P3, O6, ANIM] {
        for n in [0, 1, 2, 12, 20, f.len() / 3, f.len() / 2, f.len() - 1] {
            let _ = decode_as(Format::Jxl, &f[..n]);
        }
        let mut flipped = f.to_vec();
        for i in (0..flipped.len()).step_by(7) {
            flipped[i] ^= 0x5A;
            let _ = decode_as(Format::Jxl, &flipped);
        }
    }
    assert!(
        decode_as(Format::Jxl, &LOSSY[..LOSSY.len() / 2]).is_err()
            || decode_as(Format::Jxl, &LOSSY[..LOSSY.len() / 2]).unwrap().warnings.contains(&DecodeWarning::Truncated { format: Format::Jxl })
    );
}

#[test]
fn the_limits_are_checked_before_decoding() {
    let tiny = Limits { max_pixels: 100, ..Limits::default() };
    assert!(matches!(decode_with(LOSSY, &DecodeOptions { limits: tiny, ..Default::default() }), Err(CodecError::LimitExceeded(_))));
    let tiny = Limits { max_alloc: 64, ..Limits::default() };
    assert!(decode_with(LOSSY, &DecodeOptions { limits: tiny, ..Default::default() }).is_err());
}

#[test]
fn the_built_in_encoder_keeps_exif_and_xmp() {
    let mut img = synth(19, 7, ChannelLayout::Rgba, SampleType::U16, 3, 0.0);
    img.meta.exif = Some(sample_exif());
    img.meta.xmp = Some("<x:xmpmeta xmlns:x=\"adobe:ns:meta/\"/>".into());
    let bytes = encode(&img, Format::Jxl, &EncodeOptions::default()).unwrap();
    let back = decode(&bytes).unwrap();
    assert_eq!(back.data(), img.data(), "16-bit RGBA is exact");
    assert_eq!(back.meta.xmp, img.meta.xmp);
    let exif = back.meta.exif.as_deref().unwrap();
    assert_eq!(exif_orientation(exif), 1);

    let bare = encode(&img, Format::Jxl, &EncodeOptions { embed_metadata: false, ..Default::default() }).unwrap();
    assert!(bare.starts_with(&[0xFF, 0x0A]), "no metadata: a bare codestream");
    assert!(decode(&bare).unwrap().meta.exif.is_none());
}

#[test]
fn sixteen_bit_alpha_keeps_values_past_half_range() {
    // Both of zune-jpegxl's 16-bit alpha problems: the 8-bit alpha declaration and signed gray+alpha.
    for layout in [ChannelLayout::Rgba, ChannelLayout::GrayA] {
        let n = 5 * 4 * layout.channels();
        let px: Vec<u16> = (0..n).map(|i| (i as u32 * 65535 / (n as u32 - 1)) as u16).collect();
        let img = Image::from_u16(5, 4, layout, &px).unwrap();
        let back = decode(&encode(&img, Format::Jxl, &EncodeOptions::default()).unwrap()).unwrap();
        assert_eq!(back.convert(layout, SampleType::U16), img, "{layout:?}");
    }
}
